macro.command:
const version = "13.0.65";
const ADV_NAME = "Gloves of Soul Catching: Advantage";
// Marker on the roll's options - invisible on the card, and immune to part reordering.
const MARK = "soulCatching";
const isUnarmed = (item) => item?.system?.identifier === "unarmed-strike" || item?.name === "Unarmed Strike";

try {
  if (args[0]?.tag !== "OnUse") return;

  // preDamageRollConfig: append our 2d10 to the damage roll being built, so it is part of the
  // strike's own damage. Anything that re-types workflow.damageRolls later covers it too.
  if (args[0].macroPass === "preDamageRollConfig") {
    if (!workflow?.hitTargets?.size || !isUnarmed(rolledItem)) return;
    const config = args[0].options?.config;
    if (!config) return;
    config.rolls ??= [];
    config.rolls.push({
      parts: ["2d10"],
      data: {},
      options: { type: "force", types: ["force"], properties: [], [MARK]: true }
    });
    return;
  }

  if (args[0].macroPass !== "postDamageRoll") return;
  if (!workflow?.hitTargets?.size || !isUnarmed(rolledItem)) return;

  // Exact lookup - no index, no formula text. Doubles to 4d10 on a crit, so the heal follows suit.
  const amount = (workflow.damageRolls ?? []).find(r => r.options?.[MARK])?.total ?? 0;
  if (!amount) return;

  const hp = actor.system.attributes.hp;
  const healLabel = hp.value < hp.max ? `Regain ${amount} hit points`
    : `Regain ${amount} hit points (already at full)`;
  const choice = await foundry.applications.api.DialogV2.wait({
    window: { title: macroItem.name },
    position: { width: 420 },
    content: `<p>The gloves dealt ${amount} extra damage. Choose the benefit:</p>`,
    buttons: [
      { action: "heal", label: healLabel, default: true },
      { action: "advantage", label: "Advantage on one roll instead" },
      { action: "no", label: "Neither" }
    ],
    close: () => "no"
  });
  if (choice === "no") return;

  if (choice === "heal") {
    // Applied via applyDamage so dnd5e's damage/healing hooks fire and dependent automation
    // can react; it also clamps to max hit points for us.
    await actor.applyDamage([{ value: amount, type: "healing" }]);
  } else {
    for (const ef of actor.effects.filter(e => e.name === ADV_NAME)) await ef.delete();
    await actor.createEmbeddedDocuments("ActiveEffect", [{
      name: ADV_NAME,
      img: macroItem.img,
      origin: macroItem.uuid,
      duration: { value: 1, units: "rounds" },
      system: { changes: [{ key: "flags.midi-qol.advantage.all", type: "override", value: "1" }] },
      flags: { dae: { specialDuration: ["1Attack", "isCheck", "isSave", "isSkill"], stackable: "noneName" } }
    }]);
  }
} catch (err) {
  console.error(`Gloves of Soul Catching (Elemental) ${version}`, err);
}
